ROOT=Path(__file__).parent
LONG=[('jU3nOWkZCCQ','Dogs Almost Went Extinct And Were Saved By This Underdog','2026-07-31',1238,47129,'lineage history'),('I1q0BWE9ehQ','Why Goldfish Get So Big In The Wild','2026-08-07',1427,155604,'familiar animal / hidden growth'),('BHbZ7bO68fA',"We've Been Misreading What Our Cats Are Saying",'2026-08-14',975,123019,'communication / misconception'),('aVLhzZ6p2V8','The Most Bullied Animal In The Internet Is Full Of Secrets','2026-08-21',826,48111,'internet animal / secrets'),('aMyPWVWlJaA','The Armadillo The Size Of A Beetle (The Car)','2026-08-28',1088,68694,'extinct animal / size comparison'),('WJrBrxlBcgw','We Were Wrong About Eastern Cougars','2026-09-04',1067,200984,'range / misconception'),('VhW7Ze3USno',"There's No Such Thing As A Giraffe",'2026-09-11',1237,205022,'taxonomy / contradiction')]
SHORT=[('2c_--d3QJhA',"Cats Meow To Manipulate You - Here's Why!",'2026-08-18',68,78752,'communication'),('L3lypZkMG2w','Rock Hyrax: The Cute Creature the Internet Loves to Bully!','2026-08-28',87,19661,'internet animal'),('sCrWjOzMhe4','Giant Armadillos Were Actually REAL Armadillos','2026-09-03',73,12157,'taxonomy'),('gj_Ef8Yfqhc',"Cougar's Epic 1500-Mile Journey",'2026-09-10',53,10483,'journey'),('KAlW2Z3OcW0',"Meet the 4 Giraffe Species! You Won't Believe The Difference",'2026-09-17',77,47070,'taxonomy')]
BB=[('WXmvOjiYdvo','Scientists Built A Robot to Hunt This Starfish','2021-05-07',441,1212101,'intervention'),('2x5eOBJ37iE','The Strange Thing That Turns Grasshoppers Into Locusts','2022-03-04',368,1469654,'transformation'),('z3H6fJ3t-Cs','This Frog Is Bad At Basically Everything','2022-10-07',426,1949328,'apparent incompetence'),('KlU-CCF-j9M','Figs Eat Wasps Before You Eat The Fig','2023-02-03',374,938300,'food / hidden relationship')]
def records(raw,channel,fmt):
 return [dict(id=i,url='https://www.youtube.com/watch?v='+i,title=t,channel=channel,upload_date=d,duration_seconds=s,views=v,topic_angle=a,format=fmt,format_evidence='secondary catalogue Short badge + original title #Shorts; native player classification not independently tested' if fmt=='short' else 'original watch duration and catalogue long-form',age_days=(datetime.date(2026,11,14)-datetime.date.fromisoformat(d)).days,metadata_evidence='original watch page fetched this research pass',thumbnail_url='https://i.ytimg.com/vi/'+i+'/maxresdefault.jpg',thumbnail_inspected=False,video_playback=False) for i,t,d,s,v,a in raw]
long=records(LONG,'Animalogic','long');short=records(SHORT,'Animalogic','short');bb=records(BB,'Bizarre Beasts','long')
for subset in [long,short]:
 med=statistics.median(r['views'] for r in subset)
 for r in subset:r['descriptive_sample_median_ratio']=round(r['views']/med,3)
report={'date_basis':'2026-11-14 instructed date for age; live retrieval snapshots not archived historical counts','cohorts':[{'name':'Animalogic seven weekly standalones','n':len(long),'selection':'All seven weekly 10–25min standalone entries between Jul31 and Sep11 in recovered catalogue; interleaved long compilations excluded; independent catalogue completeness not established','median_views':statistics.median(r['views'] for r in long),'limitation':'64–106 days old; not equal-age views, sample not whole channel; extinct-topic controls are not Monarch Cam episode recommendations','rows':long},{'name':'Animalogic five catalogue-labelled Shorts','n':len(short),'selection':'Five chronological short-badged entries Aug18–Sep17 in recovered catalogue','median_views':statistics.median(r['views'] for r in short),'limitation':'small n, unequal ages/durations; native classification provisional','rows':short},{'name':'Bizarre Beasts publisher featured examples','n':len(bb),'median_views':None,'selection':'Four examples explicitly featured by publisher; curated success-biased convenience sample','limitation':'No typical/low label or outlier baseline permitted; date span2021–2023','rows':bb}],'thumbnail_recovery_attempts':['three exact-title image searches: no results','direct ytimg urllib TLS EOF; no image saved'],'batch1_passed':False}
(ROOT/'ANIMAL_PERFORMANCE_COHORTS.json').write_text(json.dumps(report,indent=2)+'\n')
print('long median',statistics.median(r['views'] for r in long),'short median',statistics.median(r['views'] for r in short))
